 public record ApprovalRow(Schedule schedule,UUID storeId,long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,List<String> issues,String sourceFingerprint,Approval approval,boolean requiresReview,@com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL) List<Finding> findings,@com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL) String fullAttendanceStatus,List<com.rpb.reservation.workforce.attendance.BreakCalculator.Summary> breakSummary,@com.fasterxml.jackson.annotation.JsonInclude(com.fasterxml.jackson.annotation.JsonInclude.Include.NON_NULL) Boolean exempt){public ApprovalRow(Schedule schedule,UUID storeId,long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,List<String> issues,String sourceFingerprint,Approval approval,boolean requiresReview,List<Finding> findings,String fullAttendanceStatus,List<com.rpb.reservation.workforce.attendance.BreakCalculator.Summary> breakSummary){this(schedule,storeId,workSeconds,paidLeaveSeconds,unpaidLeaveSeconds,issues,sourceFingerprint,approval,requiresReview,findings,fullAttendanceStatus,breakSummary,null);}public ApprovalRow(Schedule schedule,UUID storeId,long workSeconds,long paidLeaveSeconds,long unpaidLeaveSeconds,List<String> issues,String sourceFingerprint,Approval approval,boolean requiresReview){this(schedule,storeId,workSeconds,paidLeaveSeconds,unpaidLeaveSeconds,issues,sourceFingerprint,approval,requiresReview,List.of(),"pending",List.of());}}
